101	        ((ControllableClock) clock).setInstant(T0.plusSeconds(299));
102	        EscalationHistoryView view = service.checkEscalation("INC-E-001",
103	                new EscalationCheckRequest(key()));
104	        assertThat(view.current()).isNull();
105	        assertThat(view.history()).isEmpty();
