120	        ((ControllableClock) clock).setInstant(T0.plusSeconds(60));
121	        String commandKey = key();
122	        EscalationHistoryView first = service.checkEscalation("INC-E-002",
123	                new EscalationCheckRequest(commandKey));
124	        assertThat(first.current()).isNull();
125	        // 时钟越过期限后同键重放仍返回首次（无记录）结果，不重新评估
126	        ((ControllableClock) clock).setInstant(T0.plus(10, ChronoUnit.MINUTES));
