244	        // OPEN → CONTAINED：原子 CANCELLED，且遏制后不能补确认
245	        setup("INC-E-030", "S1", "alice");
246	        ((ControllableClock) clock).setInstant(T0.plus(6, ChronoUnit.MINUTES));
247	        service.checkEscalation("INC-E-030", new EscalationCheckRequest(key()));
248	        service.changeStatus("INC-E-030", "alice", new StatusRequest(key(), "CONTAINED"));
249	        EscalationView cancelled = service.escalationHistory("INC-E-030").current();
250	        assertThat(cancelled.status()).isEqualTo("CANCELLED");
251	        assertApiStatus(() -> service.acknowledgeEscalation("INC-E-030", "alice",
