261	        EscalationView kept = service.escalationHistory("INC-E-031").current();
262	        assertThat(kept.status()).isEqualTo("ACKNOWLEDGED");
263	        assertThat(kept.acknowledgedBy()).isEqualTo("alice");
264	        // 解决/关闭沿用原路径
265	        service.changeStatus("INC-E-031", "alice", new StatusRequest(key(), "RESOLVED"));
266	        service.changeStatus("INC-E-031", "alice", new StatusRequest(key(), "CLOSED"));
267	        assertThat(service.get("INC-E-031").status()).isEqualTo("CLOSED");
268	    }
