294	        assertThat(service.checkEscalation("INC-E-041", new EscalationCheckRequest(reusable))
295	                .current().status()).isEqualTo("OPEN");
296	        // 非法参数 400
297	        assertApiStatus(() -> service.checkEscalation("INC-E-041",
298	                new EscalationCheckRequest(" ")), HttpStatus.BAD_REQUEST);
299	    }
