2	
3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import java.time.Clock;
6	import java.time.Instant;
7	import java.time.temporal.ChronoUnit;
8	import java.util.ArrayList;
9	import java.util.List;
10	import java.util.UUID;
11	import java.util.concurrent.Callable;
12	import java.util.concurrent.CountDownLatch;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	
18	import com.example.starter.incident.dto.Requests.EscalationAckRequest;
19	import com.example.starter.incident.dto.Requests.EscalationCheckRequest;
20	import com.example.starter.incident.dto.Requests.ReportRequest;
21	import com.example.starter.incident.dto.Requests.StatusRequest;
22	import com.example.starter.incident.dto.Requests.TakeoverRequest;
23	import com.example.starter.incident.dto.Responses.EscalationView;
24	import com.example.starter.incident.dto.Responses.IncidentView;
25	import org.junit.jupiter.api.BeforeEach;
26	import org.junit.jupiter.api.Test;
27	import org.springframework.beans.factory.annotation.Autowired;
28	import org.springframework.boot.test.context.SpringBootTest;
29	import org.springframework.context.annotation.Import;
30	import org.springframework.jdbc.core.JdbcTemplate;
31	
32	/**
33	 * 遏制逾期并发测试：验证检查、确认与遏制在事件行锁下按事务提交顺序生效——
34	 * 遏制先提交不再新增升级；确认与遏制竞争时升级状态不可回退，不能在取消后补确认。
35	 * 使用可控 Clock 将事件置于已逾期状态，不依赖真实睡眠。
36	 */
37	@SpringBootTest
38	@Import(ControllableClock.Config.class)
39	class EscalationConcurrencyTest {
40	
41	    private static final Instant T0 = Instant.parse("2026-09-22T00:00:00Z");
42	
43	    @Autowired
44	    private IncidentService service;
45	
46	    @Autowired
47	    private JdbcTemplate jdbc;
48	
49	    @Autowired
50	    private Clock clock;
51	
52	    @BeforeEach
53	    void clean() {
54	        jdbc.update("DELETE FROM command_keys");
55	        jdbc.update("DELETE FROM incident_escalations");
56	        jdbc.update("DELETE FROM incident_status_history");
57	        jdbc.update("DELETE FROM incident_transfers");
58	        jdbc.update("DELETE FROM incident_actions");
59	        jdbc.update("DELETE FROM incident_task_blockers");
60	        jdbc.update("DELETE FROM incident_tasks");
61	        jdbc.update("DELETE FROM incidents");
62	        ((ControllableClock) clock).setInstant(T0);
63	    }
64	
65	    private static String key() {
66	        return "CMD-" + UUID.randomUUID();
67	    }
68	
69	    private void overdueCommanding(String incidentKey) {
70	        service.report(new ReportRequest(incidentKey, "S1", "并发逾期", "r"));
71	        service.takeover(incidentKey, "alice", new TakeoverRequest(key()));
72	        ((ControllableClock) clock).setInstant(T0.plus(10, ChronoUnit.MINUTES));
73	    }
74	
75	    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
76	        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
77	        try {
78	            CountDownLatch ready = new CountDownLatch(tasks.size());
79	            CountDownLatch start = new CountDownLatch(1);
80	            List<Future<Object>> futures = new ArrayList<>();
81	            for (Callable<T> task : tasks) {
82	                futures.add(pool.submit(() -> {
83	                    ready.countDown();
84	                    start.await(5, TimeUnit.SECONDS);
85	                    try {
86	                        return task.call();
87	                    } catch (Exception e) {
88	                        return e;
89	                    }
90	                }));
91	            }
92	            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
93	            start.countDown();
94	            List<Object> results = new ArrayList<>();
95	            for (Future<Object> future : futures) {
96	                results.add(future.get(30, TimeUnit.SECONDS));
97	            }
98	            return results;
99	        } finally {
100	            pool.shutdownNow();
101	        }
102	    }
103	
104	    @Test
105	    void concurrentCheckAndContain_commitOrderWins_noOpenLingers() throws Exception {
106	        for (int round = 0; round < 5; round++) {
107	            String ik = "INC-C-" + round;
108	            overdueCommanding(ik);
109	            List<Object> results = runConcurrently(List.of(
110	                    () -> service.checkEscalation(ik, new EscalationCheckRequest(key())),
111	                    () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"))));
112	            long failures = results.stream().filter(ApiException.class::isInstance).count();
113	            // 两个操作语义上都可能成功（检查在非 COMMANDING 时是空结果成功），但结果必须自洽
114	            assertThat(failures).isZero();
115	
116	            IncidentView end = service.get(ik);
117	            List<EscalationView> escalations = service.history(ik).escalations();
118	            if ("CONTAINED".equals(end.status()) && escalations.isEmpty()) {
119	                // 遏制先提交：检查不再新增升级
120	                continue;
121	            }
122	            // 检查先提交：恰好一条记录，且被同事务/随后的遏制取消，绝不残留 OPEN
123	            assertThat(end.status()).isEqualTo("CONTAINED");
124	            assertThat(escalations).hasSize(1);
125	            assertThat(escalations.get(0).status()).isEqualTo("CANCELLED");
126	        }
127	    }
128	
129	    @Test
130	    void concurrentAcknowledgeAndContain_noRollbackOrLateAck() throws Exception {
131	        String ik = "INC-C-ACK";
132	        overdueCommanding(ik);
133	        // 先产生一条 OPEN 记录
134	        service.checkEscalation(ik, new EscalationCheckRequest(key()));
135	
136	        List<Object> results = runConcurrently(List.of(
137	                () -> service.acknowledgeEscalation(ik, "alice",
138	                        new EscalationAckRequest(key(), "并发确认说明")),
139	                () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"))));
140	
141	        long acks = results.stream().filter(r -> r instanceof EscalationView).count();
142	        long conflicts = results.stream().filter(ApiException.class::isInstance)
143	                .map(ApiException.class::cast).filter(e -> e.status().value() == 409).count();
144	        long views = results.stream().filter(IncidentView.class::isInstance).count();
145	        assertThat(views).isEqualTo(1);
146	        assertThat(acks + conflicts).isEqualTo(1);
147	
148	        EscalationView end = service.escalationHistory(ik).current();
149	        if (acks == 1) {
150	            // 确认先提交：遏制保留已确认记录，状态不回退
151	            assertThat(end.status()).isEqualTo("ACKNOWLEDGED");
152	            assertThat(end.acknowledgedBy()).isEqualTo("alice");
153	            assertThat(end.note()).isEqualTo("并发确认说明");
154	        } else {
155	            // 遏制先提交：记录 CANCELLED，确认失败且之后不能补确认
